CREATE TABLE lexicon_generations(id INTEGER PRIMARY KEY AUTOINCREMENT, stamp TEXT NOT NULL, state TEXT NOT NULL, created REAL NOT NULL, published REAL, processed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE lexicon_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1), active_generation INTEGER NOT NULL DEFAULT 0, building_generation INTEGER, heartbeat REAL NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 0,updated REAL NOT NULL DEFAULT 0);
INSERT INTO lexicon_state(singleton) VALUES(1);
CREATE TABLE lexicon_terms(generation INTEGER NOT NULL,id TEXT NOT NULL,domain TEXT NOT NULL,label TEXT NOT NULL,info_json TEXT NOT NULL,photo_count INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(generation,id));
CREATE INDEX lexicon_domain ON lexicon_terms(generation,domain,photo_count DESC,id);
CREATE TABLE lexicon_aliases(generation INTEGER NOT NULL,term_id TEXT NOT NULL,normalized TEXT NOT NULL,label TEXT NOT NULL,source TEXT NOT NULL,refs INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(generation,term_id,normalized,label,source));
CREATE INDEX lexicon_alias_lookup ON lexicon_aliases(generation,normalized,term_id);
CREATE TABLE lexicon_asset_terms(generation INTEGER NOT NULL,asset_id TEXT NOT NULL,revision TEXT NOT NULL,term_id TEXT NOT NULL,evidence_json TEXT NOT NULL,PRIMARY KEY(generation,asset_id,term_id));
CREATE INDEX lexicon_term_assets ON lexicon_asset_terms(generation,term_id,asset_id);
CREATE TABLE lexicon_dirty(asset_id TEXT PRIMARY KEY,token TEXT NOT NULL);
CREATE TRIGGER lexicon_entries_insert AFTER INSERT ON entries BEGIN INSERT INTO lexicon_dirty VALUES(NEW.id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_entries_delete AFTER DELETE ON entries BEGIN INSERT INTO lexicon_dirty VALUES(OLD.id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_entries_update AFTER UPDATE OF revision,missing,scope_excluded,kind,is_dir,event_json,source_id,parent ON entries BEGIN INSERT INTO lexicon_dirty VALUES(OLD.id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_analysis_insert AFTER INSERT ON analysis BEGIN INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_analysis_delete AFTER DELETE ON analysis BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_analysis_update AFTER UPDATE OF revision,provider,version,data_json ON analysis BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_metadata_insert AFTER INSERT ON metadata BEGIN INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_metadata_delete AFTER DELETE ON metadata BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_metadata_update AFTER UPDATE OF field,layer,value_json,source_revision,stale,info_json ON metadata BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_curation_insert AFTER INSERT ON curation BEGIN INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_curation_delete AFTER DELETE ON curation BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
CREATE TRIGGER lexicon_curation_update AFTER UPDATE OF excluded ON curation BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
