CREATE TRIGGER lexicon_media_jobs_update AFTER UPDATE OF revision,status ON media_jobs BEGIN INSERT INTO lexicon_dirty VALUES(OLD.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token;INSERT INTO lexicon_dirty VALUES(NEW.asset_id,hex(randomblob(16))) ON CONFLICT(asset_id) DO UPDATE SET token=excluded.token; END;
